<?php if (!defined('__TYPECHO_ROOT_DIR__')) exit; ?><section id="comments" class="comments-area"><?php $this->comments()->to($comments); if($comments->have()): ?><h2><?php $this->commentsNum('暂无评论','1 条评论','%d 条评论'); ?></h2><?php $comments->listComments(); ?><?php $comments->pageNav('&laquo;', '&raquo;'); ?><?php endif; if($this->allow('comment')): ?><div class="respond" id="<?php $this->respondId(); ?>"><h2>留下评论</h2><form method="post" action="<?php $this->commentUrl(); ?>"><div class="identity"><?php if(!$this->user->hasLogin()): ?><input name="author" placeholder="称呼" value="<?php $this->remember('author'); ?>"><input type="email" name="mail" placeholder="邮箱" value="<?php $this->remember('mail'); ?>"><?php endif; ?></div><textarea name="text" rows="7" placeholder="我相信爱情，可是我不相信会发生在我身上..." required><?php $this->remember('text'); ?></textarea><button class="submit">提交评论</button></form></div><?php endif; ?></section>
